import java.util.Scanner;

public class GameWinner {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read the number of rounds
        int n = scanner.nextInt();
        scanner.nextLine(); // consume newline

        int powerA = 0;
        int powerB = 0;

        boolean winnerDeclared = false;

        for (int round = 0; round < n; round++) {
            String line = scanner.nextLine().trim();
            if (line.isEmpty()) {
                round--;
                continue;
            }
            String[] moves = line.split(" ");
            String moveA = moves[0];
            String moveB = moves[1];

            // Process round
            String roundResult = processRound(moveA, moveB, powerA, powerB);

            if (roundResult.equals("A")) {
                System.out.println("A");
                winnerDeclared = true;
                break;
            } else if (roundResult.equals("B")) {
                System.out.println("B");
                winnerDeclared = true;
                break;
            }

            // Update powers after the round
            if (moveA.equals("charge")) {
                powerA = Math.min(powerA + 1, 5);
            }
            if (moveB.equals("charge")) {
                powerB = Math.min(powerB + 1, 5);
            }
        }

        if (!winnerDeclared) {
            System.out.println("DRAW");
        }

        scanner.close();
    }

    private static String processRound(String moveA, String moveB, int powerA, int powerB) {
        // Handle disqualification cases
        if (moveA.equals("attack") && powerA == 0 && !(moveB.equals("attack") && powerB == 0)) {
            return "B";
        }
        if (moveB.equals("attack") && powerB == 0 && !(moveA.equals("attack") && powerA == 0)) {
            return "A";
        }
        // Both attack with 0 power -> no winner
        if (moveA.equals("attack") && powerA == 0 && moveB.equals("attack") && powerB == 0) {
            return "DRAW";
        }

        // Attack vs Attack
        if (moveA.equals("attack") && moveB.equals("attack")) {
            if (powerA > powerB) return "A";
            if (powerB > powerA) return "B";
            return "DRAW";
        }

        // Attack vs Charge
        if (moveA.equals("attack") && moveB.equals("charge")) {
            return "A";
        }
        if (moveB.equals("attack") && moveA.equals("charge")) {
            return "B";
        }

        // Attack vs Defend
        if (moveA.equals("attack") && moveB.equals("defend")) {
            if (powerA == 5) return "A";
            return "DRAW";
        }
        if (moveB.equals("attack") && moveA.equals("defend")) {
            if (powerB == 5) return "B";
            return "DRAW";
        }

        // All other cases (charge/defend vs charge/defend) -> no winner
        return "DRAW";
    }
}

